SELECT percentile_cont(0.75) within GROUP (ORDER BY MAX(labevents.value)) AS seventy_five_percentile FROM labevents JOIN admissions ON labevents.subject_id = admissions.subject_id WHERE admissions.gender = 'F' AND EXTRACT(YEAR FROM admissions.admittime) BETWEEN 2019 AND 2020 AND EXTRACT(YEAR FROM labevents.charttime) BETWEEN 2019 AND 2020 AND labevents.itemid IN (SELECT itemid FROM d_labitems WHERE category = 'Vital Signs' AND label = 'Systolic Blood Pressure') AND admissions.age BETWEEN 59 AND 69;